package com.saludintegral.paciente.services;
import org.springframework.stereotype.Service; import java.util.*; import com.saludintegral.paciente.model.Paciente; import com.saludintegral.paciente.repository.PacienteRepository; import com.saludintegral.paciente.dto.PacienteRequest;
@Service public class PacienteService {final PacienteRepository r; public PacienteService(PacienteRepository r){this.r=r;} public List<Paciente> all(){return r.findAll();} public Paciente get(Long id){return r.findById(id).orElseThrow(()->new NoSuchElementException("Paciente no encontrado: "+id));} public Paciente save(PacienteRequest x){if(r.existsByDni(x.dni()))throw new IllegalArgumentException("DNI ya registrado");return r.save(map(new Paciente(),x));} public Paciente update(Long id,PacienteRequest x){Paciente p=get(id);if(!p.dni.equals(x.dni())&&r.existsByDni(x.dni()))throw new IllegalArgumentException("DNI ya registrado");return r.save(map(p,x));} public void delete(Long id){r.delete(get(id));} Paciente map(Paciente p,PacienteRequest x){p.dni=x.dni();p.nombres=x.nombres();p.apellidos=x.apellidos();p.fechaNacimiento=x.fechaNacimiento();p.sexo=x.sexo();p.telefono=x.telefono();p.direccion=x.direccion();p.correo=x.correo();p.estado=x.estado()==null?"A":x.estado();return p;} }
